def predict(history, action):
    grid = np.array(history.frames[-1], dtype=np.int8)
    kind = int(action.kind)
    if kind == 6:
        row = int(action.row)
        col = int(action.col)
    else:
        row, col = None, None

    if kind == 1:
        # ACTION1 fills the next available row from top to bottom
        current_values = np.unique(grid.ravel())
        if 0 in current_values:
            next_val = 1
        else:
            next_val = 1

        # Find the first row that has only 0s and fill it
        for r in range(grid.shape[0]):
            row_vals = grid[r, :]
            if np.all(row_vals == 0):
                grid[r, :] = next_val
                break
    elif kind == 2:
        # ACTION2 fills the next available column from left to right
        current_values = np.unique(grid.ravel())
        if 0 in current_values:
            next_val = 1
        else:
            next_val = 1

        for c in range(grid.shape[1]):
            col_vals = grid[:, c]
            if np.all(col_vals == 0):
                grid[:, c] = next_val
                break
    elif kind == 6:
        # ACTION6 sets the specific cell
        grid[row, col] = 1

    return {"next_grid": grid, "game_state": "NOT_FINISHED", "level_delta": 0, "memory": {}}

