def predict(history, action):
    kind = int(action.kind)
    grid = np.array(history.frames[-1], dtype=np.int8)
    next_grid = grid.copy()

    if kind == 6:
        row = int(action.row)
        col = int(action.col)
        if 0 <= row < next_grid.shape[0] and 0 <= col < next_grid.shape[1]:
            next_grid[row, col] = 1
    elif kind == 1:
        # ACTION1 fills the grid from top-left
        next_grid[:] = 1
    elif kind == 2:
        # ACTION2 fills the grid from bottom-right
        next_grid[:] = 1
    else:
        # For other actions, maintain current state
        pass

    return {"next_grid": next_grid, "game_state": "NOT_FINISHED", "level_delta": 0, "memory": {}}

